// CourierFilter provides filtering for Courier queries
type CourierFilter struct {
	Id   *UUIDFilter
	Name *StringFilter
	// ReferencedByDeliveryCourier filters on the presence or absence of a
	// Delivery whose courier points at this row.
	ReferencedByDeliveryCourier *ReferencedByFilter
	// AllOf keeps the rows every one of its filters finds, beside the
	// filter's other conditions (D99): each filter's conditions are ANDed
	// with them, so two AnyOf groups, each in a filter of its own, must
	// both hold. A filter of no condition adds none, and so does an empty
	// AllOf.
	AllOf []CourierFilter
	// AnyOf keeps the rows any of its filters finds, each filter's
	// conditions ANDed and the filters ORed, beside the filter's other
	// conditions (D90). A filter of no condition keeps every row, and so
	// does an empty AnyOf.
	AnyOf []CourierFilter
}

// CourierUpdate provides fields that can be updated
type CourierUpdate struct {
	Name *string
	// UpdatedBy is automatically set if not provided and user is in context
	UpdatedBy *types.IdentityUUID
}

// NewCourierSnapshotUpdate maps every mutable field from a complete
// Courier value. It is intended for source-of-truth replacement flows;
// nullable zero values clear their columns instead of leaving stale data.
func NewCourierSnapshotUpdate(input *types.Courier) *CourierUpdate {
	update := &CourierUpdate{}
	if input == nil {
		return update
	}
	update.Name = &input.Name
	return update
}

// ApplyTo writes every set and SetNull field onto row. A nil receiver or row
// is a no-op. SetNull wins when both a value and SetNull are present.
func (u *CourierUpdate) ApplyTo(row *types.Courier) {
	if u == nil || row == nil {
		return
	}
	if u.Name != nil {
		row.Name = *u.Name
	}
}

// CourierFilterConditions are the filter's conditions for a query of
// the caller's own, each column qualified by its table: each value is
// appended to args, its placeholder numbered after those already there.
// FindMany's WHERE is them joined by AND. A nil filter has none.
func CourierFilterConditions(filter *CourierFilter, args *[]any) []string {
	return filter.conditions(args, len(*args))
}

// buildWhereClause builds a WHERE clause from a CourierFilter: its
// conditions joined by AND, or nothing when it has none.
func (f *CourierFilter) buildWhereClause(args *[]interface{}, paramOffset int) string {
	conditions := f.conditions(args, paramOffset)
	if len(conditions) == 0 {
		return ""
	}
	return " WHERE " + strings.Join(conditions, " AND ")
}

// conditions are the filter's conditions, each value appended to args, its
// placeholder numbered from paramOffset+1.
func (f *CourierFilter) conditions(args *[]interface{}, paramOffset int) []string {
	if f == nil {
		return nil
	}

	var conditions []string
	paramNum := paramOffset
	if f.Id != nil {
		if f.Id.Eq != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`courier.id = $%d`, paramNum))
			*args = append(*args, f.Id.Eq.ToUUID())
		}
		if f.Id.Ne != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`courier.id IS DISTINCT FROM $%d`, paramNum))
			*args = append(*args, f.Id.Ne.ToUUID())
		}
		if len(f.Id.In) > 0 {
			placeholders := make([]string, len(f.Id.In))
			for i, id := range f.Id.In {
				paramNum++
				placeholders[i] = fmt.Sprintf("$%d", paramNum)
				*args = append(*args, id.ToUUID())
			}
			conditions = append(conditions, fmt.Sprintf(`courier.id IN (%s)`, strings.Join(placeholders, ", ")))
		}
		if len(f.Id.NotIn) > 0 {
			placeholders := make([]string, len(f.Id.NotIn))
			for i, id := range f.Id.NotIn {
				paramNum++
				placeholders[i] = fmt.Sprintf("$%d", paramNum)
				*args = append(*args, id.ToUUID())
			}
			conditions = append(conditions, fmt.Sprintf(`(courier.id IN (%s)) IS NOT TRUE`, strings.Join(placeholders, ", ")))
		}
		if f.Id.IsNull != nil {
			if *f.Id.IsNull {
				conditions = append(conditions, `courier.id IS NULL`)
			} else {
				conditions = append(conditions, `courier.id IS NOT NULL`)
			}
		}
	}
	if f.Name != nil {
		if f.Name.Eq != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`courier."name" = $%d`, paramNum))
			*args = append(*args, *f.Name.Eq)
		}
		if f.Name.Ne != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`courier."name" IS DISTINCT FROM $%d`, paramNum))
			*args = append(*args, *f.Name.Ne)
		}
		if len(f.Name.In) > 0 {
			placeholders := make([]string, len(f.Name.In))
			for i, value := range f.Name.In {
				paramNum++
				placeholders[i] = fmt.Sprintf("$%d", paramNum)
				*args = append(*args, value)
			}
			conditions = append(conditions, fmt.Sprintf(`courier."name" IN (%s)`, strings.Join(placeholders, ", ")))
		}
		if len(f.Name.NotIn) > 0 {
			placeholders := make([]string, len(f.Name.NotIn))
			for i, value := range f.Name.NotIn {
				paramNum++
				placeholders[i] = fmt.Sprintf("$%d", paramNum)
				*args = append(*args, value)
			}
			conditions = append(conditions, fmt.Sprintf(`(courier."name" IN (%s)) IS NOT TRUE`, strings.Join(placeholders, ", ")))
		}
		if f.Name.ILike != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`courier."name" ILIKE $%d`, paramNum))
			*args = append(*args, "%"+*f.Name.ILike+"%")
		}
		if f.Name.IsNull != nil {
			if *f.Name.IsNull {
				conditions = append(conditions, `courier."name" IS NULL`)
			} else {
				conditions = append(conditions, `courier."name" IS NOT NULL`)
			}
		}
	}
	if f.ReferencedByDeliveryCourier != nil {
		probe := `SELECT 1 FROM delivery WHERE delivery.courier_id = courier.id`
		if f.ReferencedByDeliveryCourier.Exists {
			conditions = append(conditions, fmt.Sprintf(`EXISTS (%s)`, probe))
		} else {
			conditions = append(conditions, fmt.Sprintf(`NOT EXISTS (%s)`, probe))
		}
	}

	// AllOf's filters' conditions are the filter's own, ANDed (D99), each
	// one's placeholders numbered after the last.
	for i := range f.AllOf {
		before := len(*args)
		conditions = append(conditions, f.AllOf[i].conditions(args, paramNum)...)
		paramNum += len(*args) - before
	}

	if len(f.AnyOf) > 0 {
		start := len(*args)
		branches := make([]string, 0, len(f.AnyOf))
		every := false
		for i := range f.AnyOf {
			before := len(*args)
			branch := f.AnyOf[i].conditions(args, paramNum)
			paramNum += len(*args) - before
			if len(branch) == 0 {
				every = true
				continue
			}
			branches = append(branches, "("+strings.Join(branch, " AND ")+")")
		}
		if every {
			// A branch of no condition keeps every row, and so does the
			// whole: the other branches' parameters go too. AnyOf is the
			// last condition, so no placeholder follows theirs.
			*args = (*args)[:start]
		} else {
			conditions = append(conditions, "("+strings.Join(branches, " OR ")+")")
		}
	}

	return conditions
}

// DeliveryFilter provides filtering for Delivery queries
type DeliveryFilter struct {
	Id          *UUIDFilter
	Address     *StringFilter
	PlanVersion *Int64Filter
	Attempts    *Int64Filter
	Proof       *StringFilter
	RunVersion  *Int64Filter
	Note        *StringFilter
	UpdatedAt   *DateTimeFilter
	// CourierID allows filtering by foreign key
	CourierID *UUIDFilter
	// Courier keeps the rows whose courier is among the Courier rows
	// the filter finds (D90): one condition, the foreign key in the keys of
	// those rows, so a row whose courier is null is not kept.
	Courier *CourierFilter
	// AllOf keeps the rows every one of its filters finds, beside the
	// filter's other conditions (D99): each filter's conditions are ANDed
	// with them, so two AnyOf groups, each in a filter of its own, must
	// both hold. A filter of no condition adds none, and so does an empty
	// AllOf.
	AllOf []DeliveryFilter
	// AnyOf keeps the rows any of its filters finds, each filter's
	// conditions ANDed and the filters ORed, beside the filter's other
	// conditions (D90). A filter of no condition keeps every row, and so
	// does an empty AnyOf.
	AnyOf []DeliveryFilter
}

// DeliveryUpdate provides fields that can be updated
type DeliveryUpdate struct {
	Address      *string
	PlanVersion  *types.GenericInt64
	Attempts     *types.GenericInt64
	Proof        *string
	ProofSetNull bool
	RunVersion   *types.GenericInt64
	Note         *string
	NoteSetNull  bool
	// CourierID allows updating the foreign key for courier
	CourierID        *types.IdentityUUID
	CourierIDSetNull bool
	// UpdatedBy is automatically set if not provided and user is in context
	UpdatedBy *types.IdentityUUID
}

// NewDeliverySnapshotUpdate maps every mutable field from a complete
// Delivery value. It is intended for source-of-truth replacement flows;
// nullable zero values clear their columns instead of leaving stale data.
func NewDeliverySnapshotUpdate(input *types.Delivery) *DeliveryUpdate {
	update := &DeliveryUpdate{}
	if input == nil {
		return update
	}
	update.Address = &input.Address
	update.PlanVersion = &input.PlanVersion
	update.Attempts = &input.Attempts
	var zeroProof string
	if input.Proof == zeroProof {
		update.ProofSetNull = true
	} else {
		update.Proof = &input.Proof
	}
	update.RunVersion = &input.RunVersion
	var zeroNote string
	if input.Note == zeroNote {
		update.NoteSetNull = true
	} else {
		update.Note = &input.Note
	}
	return update
}

// ApplyTo writes every set and SetNull field onto row. A nil receiver or row
// is a no-op. SetNull wins when both a value and SetNull are present.
func (u *DeliveryUpdate) ApplyTo(row *types.Delivery) {
	if u == nil || row == nil {
		return
	}
	if u.Address != nil {
		row.Address = *u.Address
	}
	if u.PlanVersion != nil {
		row.PlanVersion = *u.PlanVersion
	}
	if u.Attempts != nil {
		row.Attempts = *u.Attempts
	}
	if u.ProofSetNull {
		var zeroProof string
		row.Proof = zeroProof
	} else if u.Proof != nil {
		row.Proof = *u.Proof
	}
	if u.RunVersion != nil {
		row.RunVersion = *u.RunVersion
	}
	if u.NoteSetNull {
		var zeroNote string
		row.Note = zeroNote
	} else if u.Note != nil {
		row.Note = *u.Note
	}
	if u.CourierIDSetNull {
		row.Courier = nil
	} else if u.CourierID != nil {
		if row.Courier == nil {
			row.Courier = &types.Courier{}
		}
		row.Courier.Id = u.CourierID
	}
}

